const projects=window.portfolioProjects,grid=document.querySelector('#project-grid'),dialog=document.querySelector('#project-dialog');
const escapeHtml=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const icons={chart:'<path d="M3 3v18h18M6 15l4-5 4 3 6-8"/>',check:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M8 12l3 3 5-6"/>',data:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M9 9v11M9 14h12"/>',cube:'<path d="M12 2l9 5v10l-9 5-9-5V7l9-5zM3 7l9 5 9-5M12 12v10"/>',code:'<path d="M8 6l-6 6 6 6M16 6l6 6-6 6M14 3l-4 18"/>'};
function art(p){
if(p.visual==='monitor')return '<div class="project-art monitor-art"><div class="mini-window"><div class="mini-top"><span>▦ PAINEL INDUSTRIAL</span><span>MONITORAMENTO</span></div><div class="mini-body"><aside>▦<br>▥<br>⚙</aside><div class="monitor-content"><div class="mini-heading">Visão geral das prensas <span>● CONECTADO</span></div><div class="machine-grid">'+Array.from({length:6},(_,i)=>'<div class="machine '+(i===4?'warning':'')+'"><small>PRENSA 0'+(i+1)+'</small><div class="machine-line"><i></i><i></i><i></i><i></i></div><span>'+(i===4?'EM ATENÇÃO':'EM PRODUÇÃO')+'</span></div>').join('')+'</div><svg class="mini-chart" viewBox="0 0 500 60" preserveAspectRatio="none" aria-hidden="true"><path d="M0 54L20 38 50 42 80 18 110 25 140 10 170 35 200 25 230 30 260 6 290 19 320 14 350 28 380 10 410 21 440 9 470 17 500 5" fill="none" stroke="#b5e865" stroke-width="2"/></svg></div></div></div><span class="art-caption">REPRESENTAÇÃO ILUSTRATIVA</span></div>';
if(p.visual==='game')return '<div class="project-art game-art"><img src="assets/game-hero.webp" alt="Arte de motociclistas do projeto Desafio Freedom" loading="lazy"><div class="game-overlay"><small>DOIS MODOS. UM DESAFIO.</small><strong>DESAFIO<br>FREEDOM<span>↗</span></strong></div></div>';
if(p.visual==='service')return '<div class="project-art service-art"><div class="service-word"><small>ASSISTÊNCIA TÉCNICA</small><strong>EletroSilva<span>OS</span></strong><p>Organização em cada atendimento.</p><div>＋<br>＋</div></div><div class="phone"><div class="phone-top">EletroSilva <span>●</span></div><small>PAINEL DE SERVIÇOS</small><strong>Seu dia, organizado.</strong><div class="phone-summary"><div><b>OS</b><span>Atendimentos</span></div><div><b>↗</b><span>Gestão</span></div></div><div class="phone-row"><i>01</i><div><b>Ordem de serviço</b><span>Atendimento técnico</span></div><em>ABERTA</em></div><div class="phone-row"><i>02</i><div><b>Ordem de serviço</b><span>Atendimento técnico</span></div><em>EM CURSO</em></div><div class="phone-nav">⌂ <span>▦</span> ◉</div></div><span class="art-caption">REPRESENTAÇÃO ILUSTRATIVA</span></div>';
if(p.visual==='website')return '<div class="project-art website-art"><img src="assets/site-helder.png" alt="Captura da página inicial do site Painel Elétrico" loading="lazy"><span class="art-caption">CAPTURA DO PROJETO</span></div>';
return '';}
function renderProjects(filter='all'){const selected=projects.filter(p=>filter==='all'||p.category===filter);grid.innerHTML=selected.map(p=>'<article class="project-card '+(p.featured?'featured':'compact')+'">'+art(p)+'<div class="card-body">'+(!p.featured?'<div class="project-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true">'+icons[p.icon]+'</svg></div>':'')+'<p class="project-label">'+p.label+'</p><h3>'+escapeHtml(p.title)+'</h3><p class="description">'+escapeHtml(p.description)+'</p><div class="tags">'+p.tech.map(t=>'<span>'+escapeHtml(t)+'</span>').join('')+(p.pending?'<span class="pending-tag">Detalhes em breve</span>':'')+(p.status?'<span>'+escapeHtml(p.status)+'</span>':'')+'</div><div class="card-footer">'+(p.pending?'<a class="text-link" href="https://github.com/'+p.repo+'" target="_blank" rel="noopener noreferrer">Repositório informado <span>↗</span></a>':'<button class="detail-button" data-project="'+p.id+'">Conhecer projeto <span>↗</span></button><a class="repo-link" href="https://github.com/'+p.repo+'" target="_blank" rel="noopener noreferrer" aria-label="Ver '+escapeHtml(p.title)+' no GitHub"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">'+icons.code+'</svg></a>')+'</div></div></article>').join('');document.querySelector('#result-count').textContent=selected.length+' '+(selected.length===1?'projeto':'projetos');}
document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(item=>{item.classList.toggle('active',item===b);item.setAttribute('aria-pressed',String(item===b));});renderProjects(b.dataset.filter);}));
grid.addEventListener('click',e=>{const b=e.target.closest('[data-project]');if(!b)return;const p=projects.find(p=>p.id===b.dataset.project);document.querySelector('#dialog-content').innerHTML='<p class="eyebrow">'+p.label+'</p><h2 id="dialog-title">'+escapeHtml(p.title)+'</h2><p class="description">'+escapeHtml(p.description)+'</p><h3>O que você encontra no projeto</h3><ul>'+p.features.map(f=>'<li>'+escapeHtml(f)+'</li>').join('')+'</ul><div class="tags">'+p.tech.map(t=>'<span>'+escapeHtml(t)+'</span>').join('')+'</div>'+(p.status?'<p class="note">'+p.status+'</p>':'')+'<a class="button primary" href="https://github.com/'+p.repo+'" target="_blank" rel="noopener noreferrer">Explorar código no GitHub <span>↗</span></a>';dialog.showModal();document.body.classList.add('dialog-open');});
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('dialog-open'));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');nav.classList.toggle('open',open);});nav.addEventListener('click',e=>{if(e.target.closest('a')){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu');nav.classList.remove('open');}});
document.querySelector('#year').textContent=new Date().getFullYear();renderProjects();